sed -i '/Decode google-services.json/,/fi/c\      - name: Decode google-services.json\n        env:\n          GOOGLE_SERVICES_JSON: ${{ secrets.GOOGLE_SERVICES_JSON_BASE64 }}\n        run: |\n          printf "%s" "$GOOGLE_SERVICES_JSON" > app/google-services.json\n          if jq -e . app/google-services.json >/dev/null 2>&1; then\n            echo "Secret is raw valid JSON. Using as is."\n          else\n            echo "Secret is not raw valid JSON. Attempting to base64 decode..."\n            printf "%s" "$GOOGLE_SERVICES_JSON" | base64 -d > app/google-services.json\n            if jq -e . app/google-services.json >/dev/null 2>&1; then\n              echo "Successfully decoded base64 JSON."\n            else\n              echo "ERROR: The decoded output is still not valid JSON. Please check your GitHub Secret."\n              exit 1\n            fi\n          fi' .github/workflows/release.yml
